import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const outputPath = resolve(process.cwd(), 'docs/reference/generated/action-note.md');
const contents = [
  '# Action Note',
  '',
  'Generated by the fixture Skopos Action.',
  '',
  '- source: `tools/skopos/actions/docs-generate-note.yaml`',
  '- purpose: prove Action discovery and execution',
  '',
].join('\n');

await mkdir(dirname(outputPath), { recursive: true });
await writeFile(outputPath, contents, 'utf8');
